-- ================================================================
-- 0. ENABLE EXTENSIONS
-- ================================================================
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";


-- ================================================================
-- 1. CUSTOM TYPES (Enums)
-- ================================================================

-- Role enum: controls access levels throughout the app
CREATE TYPE user_role AS ENUM ('user', 'admin', 'superadmin');

-- Report status enum: tracks moderation workflow
CREATE TYPE report_status AS ENUM ('pending', 'resolved', 'dismissed');

-- Admin action types: for the activity log
CREATE TYPE admin_action_type AS ENUM (
    'delete_post',
    'lock_user',
    'unlock_user',
    'suspend_user',
    'unsuspend_user',
    'ban_user',
    'delete_account',
    'promote_to_admin',
    'demote_from_admin',
    'resolve_report',
    'dismiss_report'
);


-- ================================================================
-- 2. PROFILES TABLE
-- ================================================================
-- Extends Supabase auth.users with app-specific data.
-- Created automatically via trigger when a new user signs up.

CREATE TABLE profiles (
    id UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
    username TEXT UNIQUE NOT NULL,
    email TEXT NOT NULL,
    role user_role NOT NULL DEFAULT 'user',
    is_verified BOOLEAN NOT NULL DEFAULT false,
    is_suspended BOOLEAN NOT NULL DEFAULT false,
    suspended_until TIMESTAMPTZ DEFAULT NULL,   -- NULL = permanent if is_suspended is true
    suspension_reason TEXT DEFAULT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Indexes for profiles
CREATE INDEX idx_profiles_username ON profiles(username);
CREATE INDEX idx_profiles_email ON profiles(email);
CREATE INDEX idx_profiles_role ON profiles(role);
CREATE INDEX idx_profiles_is_suspended ON profiles(is_suspended) WHERE is_suspended = true;
CREATE INDEX idx_profiles_created_at ON profiles(created_at DESC);


-- ================================================================
-- 3. CONFESSIONS TABLE
-- ================================================================

CREATE TABLE confessions (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    user_id UUID NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
    content TEXT NOT NULL CHECK (char_length(content) <= 1000 AND char_length(content) > 0),
    likes_count INTEGER NOT NULL DEFAULT 0 CHECK (likes_count >= 0),
    is_deleted BOOLEAN NOT NULL DEFAULT false,
    deleted_by UUID REFERENCES profiles(id) ON DELETE SET NULL DEFAULT NULL,
    deleted_at TIMESTAMPTZ DEFAULT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Indexes for confessions
CREATE INDEX idx_confessions_user_id ON confessions(user_id);
CREATE INDEX idx_confessions_created_at ON confessions(created_at DESC);
CREATE INDEX idx_confessions_likes_count ON confessions(likes_count DESC);
CREATE INDEX idx_confessions_is_deleted ON confessions(is_deleted);
-- Composite index for feed queries (non-deleted, ordered by time)
CREATE INDEX idx_confessions_feed ON confessions(created_at DESC) WHERE is_deleted = false;
-- Composite index for trending queries (non-deleted, ordered by likes)
CREATE INDEX idx_confessions_trending ON confessions(likes_count DESC, created_at DESC) WHERE is_deleted = false;
-- Index for rate limiting (user's posts today)
CREATE INDEX idx_confessions_user_daily ON confessions(user_id, created_at DESC);


-- ================================================================
-- 4. REPORTS TABLE
-- ================================================================

CREATE TABLE reports (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    confession_id UUID NOT NULL REFERENCES confessions(id) ON DELETE CASCADE,
    reported_by UUID NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
    reason TEXT NOT NULL CHECK (char_length(reason) <= 500 AND char_length(reason) > 0),
    details TEXT DEFAULT NULL CHECK (details IS NULL OR char_length(details) <= 500),
    status report_status NOT NULL DEFAULT 'pending',
    resolved_by UUID REFERENCES profiles(id) ON DELETE SET NULL DEFAULT NULL,
    resolved_at TIMESTAMPTZ DEFAULT NULL,
    resolution_note TEXT DEFAULT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    -- Prevent duplicate reports from the same user on the same post
    UNIQUE(confession_id, reported_by)
);

-- Indexes for reports
CREATE INDEX idx_reports_confession_id ON reports(confession_id);
CREATE INDEX idx_reports_reported_by ON reports(reported_by);
CREATE INDEX idx_reports_status ON reports(status);
CREATE INDEX idx_reports_pending ON reports(created_at DESC) WHERE status = 'pending';
CREATE INDEX idx_reports_resolved_by ON reports(resolved_by) WHERE resolved_by IS NOT NULL;


-- ================================================================
-- 5. LIKES TABLE
-- ================================================================

CREATE TABLE likes (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    confession_id UUID NOT NULL REFERENCES confessions(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    -- Prevent duplicate likes
    UNIQUE(confession_id, user_id)
);

-- Indexes for likes
CREATE INDEX idx_likes_confession_id ON likes(confession_id);
CREATE INDEX idx_likes_user_id ON likes(user_id);


-- ================================================================
-- 6. ADMIN_ACTIONS TABLE (Activity Log)
-- ================================================================

CREATE TABLE admin_actions (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    admin_id UUID NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
    action_type admin_action_type NOT NULL,
    target_user_id UUID REFERENCES profiles(id) ON DELETE SET NULL DEFAULT NULL,
    target_confession_id UUID REFERENCES confessions(id) ON DELETE SET NULL DEFAULT NULL,
    notes TEXT DEFAULT NULL,
    metadata JSONB DEFAULT NULL,  -- For storing extra context (suspension duration, etc.)
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Indexes for admin_actions
CREATE INDEX idx_admin_actions_admin_id ON admin_actions(admin_id);
CREATE INDEX idx_admin_actions_action_type ON admin_actions(action_type);
CREATE INDEX idx_admin_actions_target_user ON admin_actions(target_user_id);
CREATE INDEX idx_admin_actions_created_at ON admin_actions(created_at DESC);


-- ================================================================
-- 7. FUNCTIONS
-- ================================================================

-- 7a. Auto-create profile on signup
-- This trigger function runs after a new user signs up via Supabase Auth.
-- It creates a corresponding row in the profiles table.
CREATE OR REPLACE FUNCTION handle_new_user()
RETURNS TRIGGER AS $$
BEGIN
    INSERT INTO profiles (id, username, email, role, is_verified)
    VALUES (
        NEW.id,
        COALESCE(NEW.raw_user_meta_data->>'username', 'user_' || LEFT(NEW.id::text, 8)),
        NEW.email,
        'user',
        COALESCE(NEW.email_confirmed_at IS NOT NULL, false)
    );
    RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Trigger: fires after INSERT on auth.users
CREATE OR REPLACE TRIGGER on_auth_user_created
    AFTER INSERT ON auth.users
    FOR EACH ROW
    EXECUTE FUNCTION handle_new_user();


-- 7b. Update email verification status when user confirms email
CREATE OR REPLACE FUNCTION handle_user_email_verified()
RETURNS TRIGGER AS $$
BEGIN
    IF NEW.email_confirmed_at IS NOT NULL AND OLD.email_confirmed_at IS NULL THEN
        UPDATE profiles
        SET is_verified = true, updated_at = NOW()
        WHERE id = NEW.id;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE TRIGGER on_auth_user_verified
    AFTER UPDATE OF email_confirmed_at ON auth.users
    FOR EACH ROW
    EXECUTE FUNCTION handle_user_email_verified();


-- 7c. Increment likes_count when a like is added
CREATE OR REPLACE FUNCTION increment_likes_count()
RETURNS TRIGGER AS $$
BEGIN
    UPDATE confessions
    SET likes_count = likes_count + 1
    WHERE id = NEW.confession_id;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE TRIGGER on_like_added
    AFTER INSERT ON likes
    FOR EACH ROW
    EXECUTE FUNCTION increment_likes_count();


-- 7d. Decrement likes_count when a like is removed
CREATE OR REPLACE FUNCTION decrement_likes_count()
RETURNS TRIGGER AS $$
BEGIN
    UPDATE confessions
    SET likes_count = GREATEST(likes_count - 1, 0)
    WHERE id = OLD.confession_id;
    RETURN OLD;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE TRIGGER on_like_removed
    AFTER DELETE ON likes
    FOR EACH ROW
    EXECUTE FUNCTION decrement_likes_count();


-- 7e. Auto-update updated_at timestamp on profiles
CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE TRIGGER update_profiles_updated_at
    BEFORE UPDATE ON profiles
    FOR EACH ROW
    EXECUTE FUNCTION update_updated_at_column();


-- 7f. Helper: Check if a user's suspension has expired
-- This can be called by the middleware or by a scheduled function.
CREATE OR REPLACE FUNCTION check_suspension_expired(user_uuid UUID)
RETURNS BOOLEAN AS $$
DECLARE
    profile_record RECORD;
BEGIN
    SELECT is_suspended, suspended_until INTO profile_record
    FROM profiles
    WHERE id = user_uuid;

    IF profile_record.is_suspended = true AND profile_record.suspended_until IS NOT NULL THEN
        IF profile_record.suspended_until < NOW() THEN
            -- Suspension expired, auto-unsuspend
            UPDATE profiles
            SET is_suspended = false,
                suspended_until = NULL,
                suspension_reason = NULL,
                updated_at = NOW()
            WHERE id = user_uuid;
            RETURN false; -- No longer suspended
        END IF;
        RETURN true; -- Still suspended
    END IF;

    RETURN profile_record.is_suspended; -- Could be permanently suspended (no until date)
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;


-- 7g. Helper: Count user's confessions posted today (for rate limiting)
CREATE OR REPLACE FUNCTION count_user_confessions_today(user_uuid UUID)
RETURNS INTEGER AS $$
DECLARE
    post_count INTEGER;
BEGIN
    SELECT COUNT(*)::INTEGER INTO post_count
    FROM confessions
    WHERE user_id = user_uuid
    AND created_at >= CURRENT_DATE
    AND is_deleted = false;

    RETURN post_count;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;


-- 7h. Helper: Get user role
CREATE OR REPLACE FUNCTION get_user_role(user_uuid UUID)
RETURNS user_role AS $$
DECLARE
    user_role_val user_role;
BEGIN
    SELECT role INTO user_role_val
    FROM profiles
    WHERE id = user_uuid;

    RETURN user_role_val;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;


-- 7i. Helper: Check if user is admin or superadmin
CREATE OR REPLACE FUNCTION is_admin_or_above(user_uuid UUID)
RETURNS BOOLEAN AS $$
BEGIN
    RETURN EXISTS (
        SELECT 1 FROM profiles
        WHERE id = user_uuid
        AND role IN ('admin', 'superadmin')
    );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;


-- 7j. Helper: Check if user is superadmin
CREATE OR REPLACE FUNCTION is_superadmin(user_uuid UUID)
RETURNS BOOLEAN AS $$
BEGIN
    RETURN EXISTS (
        SELECT 1 FROM profiles
        WHERE id = user_uuid
        AND role = 'superadmin'
    );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;


-- ================================================================
-- 8. ROW LEVEL SECURITY (RLS) POLICIES
-- ================================================================

-- Enable RLS on all tables
ALTER TABLE profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE confessions ENABLE ROW LEVEL SECURITY;
ALTER TABLE reports ENABLE ROW LEVEL SECURITY;
ALTER TABLE likes ENABLE ROW LEVEL SECURITY;
ALTER TABLE admin_actions ENABLE ROW LEVEL SECURITY;


-- ────────────────────────────────────
-- 8a. PROFILES POLICIES
-- ────────────────────────────────────

-- Anyone can read basic profile info (needed for username display etc.)
CREATE POLICY "profiles_select_public"
    ON profiles FOR SELECT
    USING (true);

-- Users can only update their own profile (but NOT role, is_suspended fields)
CREATE POLICY "profiles_update_own"
    ON profiles FOR UPDATE
    USING (auth.uid() = id)
    WITH CHECK (
        auth.uid() = id
        AND role = (SELECT role FROM profiles WHERE id = auth.uid())  -- Can't change own role
        AND is_suspended = (SELECT is_suspended FROM profiles WHERE id = auth.uid())  -- Can't unsuspend self
    );

-- Admins/superadmins can update any profile (for moderation actions)
CREATE POLICY "profiles_update_admin"
    ON profiles FOR UPDATE
    USING (is_admin_or_above(auth.uid()))
    WITH CHECK (is_admin_or_above(auth.uid()));

-- Only superadmin can delete profiles
CREATE POLICY "profiles_delete_superadmin"
    ON profiles FOR DELETE
    USING (is_superadmin(auth.uid()));


-- ────────────────────────────────────
-- 8b. CONFESSIONS POLICIES
-- ────────────────────────────────────

-- Anyone (even unauthenticated) can read non-deleted confessions
CREATE POLICY "confessions_select_public"
    ON confessions FOR SELECT
    USING (is_deleted = false);

-- Admins can see all confessions including deleted ones  
CREATE POLICY "confessions_select_admin"
    ON confessions FOR SELECT
    USING (is_admin_or_above(auth.uid()));

-- Authenticated, non-suspended users can create confessions
CREATE POLICY "confessions_insert_auth"
    ON confessions FOR INSERT
    WITH CHECK (
        auth.uid() = user_id
        AND NOT EXISTS (
            SELECT 1 FROM profiles
            WHERE id = auth.uid()
            AND is_suspended = true
        )
    );

-- Users can soft-delete their own confessions
CREATE POLICY "confessions_update_own"
    ON confessions FOR UPDATE
    USING (auth.uid() = user_id)
    WITH CHECK (auth.uid() = user_id);

-- Admins can update/delete any confession
CREATE POLICY "confessions_update_admin"
    ON confessions FOR UPDATE
    USING (is_admin_or_above(auth.uid()))
    WITH CHECK (is_admin_or_above(auth.uid()));

-- Allow cascade deletes when a user account is deleted
CREATE POLICY "confessions_delete_cascade"
    ON confessions FOR DELETE
    USING (
        auth.uid() = user_id 
        OR is_superadmin(auth.uid())
    );


-- ────────────────────────────────────
-- 8c. REPORTS POLICIES
-- ────────────────────────────────────

-- Authenticated users can create reports (on posts they didn't write)
CREATE POLICY "reports_insert_auth"
    ON reports FOR INSERT
    WITH CHECK (
        auth.uid() = reported_by
        AND NOT EXISTS (
            SELECT 1 FROM confessions
            WHERE id = confession_id AND user_id = auth.uid()
        )
    );

-- Users can view their own reports
CREATE POLICY "reports_select_own"
    ON reports FOR SELECT
    USING (auth.uid() = reported_by);

-- Admins can view all reports
CREATE POLICY "reports_select_admin"
    ON reports FOR SELECT
    USING (is_admin_or_above(auth.uid()));

-- Only admins can update reports (resolve/dismiss)
CREATE POLICY "reports_update_admin"
    ON reports FOR UPDATE
    USING (is_admin_or_above(auth.uid()))
    WITH CHECK (is_admin_or_above(auth.uid()));


-- ────────────────────────────────────
-- 8d. LIKES POLICIES
-- ────────────────────────────────────

-- Anyone can see likes (for counts)
CREATE POLICY "likes_select_public"
    ON likes FOR SELECT
    USING (true);

-- Authenticated users can add likes
CREATE POLICY "likes_insert_auth"
    ON likes FOR INSERT
    WITH CHECK (auth.uid() = user_id);

-- Users can remove their own likes
CREATE POLICY "likes_delete_own"
    ON likes FOR DELETE
    USING (auth.uid() = user_id);


-- ────────────────────────────────────
-- 8e. ADMIN_ACTIONS POLICIES
-- ────────────────────────────────────

-- Only admins/superadmins can insert actions
CREATE POLICY "admin_actions_insert"
    ON admin_actions FOR INSERT
    WITH CHECK (is_admin_or_above(auth.uid()) AND auth.uid() = admin_id);

-- Only superadmins can view the activity log
CREATE POLICY "admin_actions_select_superadmin"
    ON admin_actions FOR SELECT
    USING (is_superadmin(auth.uid()));

-- Admins can view their own actions
CREATE POLICY "admin_actions_select_own"
    ON admin_actions FOR SELECT
    USING (auth.uid() = admin_id);


